// Source: js/class/fonctionnalite/alliance/Actualiser.js
Utils.register(class Actualiser extends FonctionnaliteAlliance {
    /**
     * @property {string[]} ABREVIATIONS_HISTORY - Historique des abréviations
     */
    static ABREVIATIONS_HISTORY = ['ACT'];

    /**
     * @property {string} NIVEAU_DROIT_OUTIIIL_REQUIS - Niveau de droit requis pour cette fonctionnalité
     */
    static NIVEAU_DROIT_OUTIIIL_REQUIS = 'A';

    /**
     * @property {boolean} VERIFICATION_MEMBRE_REQUIS - Vérification de l'état de membre requis pour cette fonctionnalité
     */
    static VERIFICATION_MEMBRE_REQUIS = false;

    /**
     * Exécute la fonctionnalité.
     * @async
     * @returns {Promise<void>}
     */
    async run() {
        const dtButtonsContainer = $("#tabMembresAlliance_wrapper .dt-buttons");
        if (dtButtonsContainer.length > 0) {
            const bouton = $(`<a id="o_actualiserAlliance" class="dt-button" href="#"><span>Actualiser l'alliance</span></a>`);
            bouton.onActionSecurisee('click', this, this.actualiserAlliance.bind(this));
            dtButtonsContainer.prepend(bouton);
        }
    }

    /**
     * Gère le clic sur le bouton d'actualisation.
     * @async
     * @param {Event} e - L'événement de clic.
     */
    async actualiserAlliance(e) {
        e.preventDefault();

        try {
            await this.page.synchroniserJoueursDepuisDOM();

            const membresForum = await this.chargerObjetsForum(Joueur, false);
            const membresForumMap = new Map();
            for (const m of membresForum) {
                membresForumMap.set(await m.lire('Pseudo'), m);
            }

            const promessesProfil = [];
            for (const pseudo in this.page._alliance.joueurs) {
                let joueurForum = membresForumMap.get(pseudo);

                if (!joueurForum) {
                    joueurForum = new Joueur(this, { donneesInitiales: { 'Pseudo': pseudo, 'Alliance Rattachement': this.page._alliance.tag } });
                    if (await joueurForum.estJoueurCourant()) {
                        joueurForum.ecrire('Version Extension', VERSION);
                    }
                    promessesProfil.push(joueurForum.enregistrerSurForum());
                }

            }
            await Promise.all(promessesProfil);

            if (promessesProfil.length > 0) {
                const fonctionnaliteModifierGrade = new ModifierGrade(this.page);
                await fonctionnaliteModifierGrade.init();
            }

            $.toast({ ...TOAST_SUCCESS, text: "L'alliance a été mise à jour avec succès." });
        } catch (error) {
            console.error("Erreur lors de l'actualisation de l'alliance:", error);
            $.toast({ ...TOAST_ERROR, heading: "Erreur Actualisation", text: `${error.message || 'Une erreur est survenue.'}` });
        }
    }
});

;
// Source: js/class/fonctionnalite/alliance/DonneesPrivees.js
Utils.register(class DonneesPrivees extends FonctionnaliteAlliance {
    /**
     * @property {string[]} ABREVIATIONS_HISTORY - Historique des abréviations
     */
    static ABREVIATIONS_HISTORY = ['DPR'];

    /**
     * Exécute la fonctionnalité.
     * @async
     * @returns {Promise<void>}
     */
    async run() {
        let membresForum;
        await this.executerTransaction(async () => {
            membresForum = await this.chargerObjetsForum(Joueur, false);
        });

        const membresForumMap = new Map();
        for (const j of membresForum) {
            membresForumMap.set(await j.lire('Pseudo'), j);
        }

        const initialPseudoColIndex = this.page.getColonneIndex('Pseudo');
        const initialRangColIndex = this.page.getColonneIndex('Rang');
        let gradeColIndex = this.page.getColonneIndex('Grade');

        if (gradeColIndex === -1) {
            // La colonne 'Grade' n'existe pas, on la crée
            console.log(`[${this.constructor.name}] Création de la colonne 'Grade'.`);
            $('<th class="dt-head-center">Grade</th>').insertBefore($(`#tabMembresAlliance thead tr th:eq(${initialRangColIndex})`));

            const promises = $("#tabMembresAlliance tbody tr").map(async (i, elt) => {
                const row = $(elt);
                const pseudo = row.find(`td:eq(${initialPseudoColIndex})`).text().split(' ')[0];
                const joueur = membresForumMap.get(pseudo);

                let grade = '';
                if (joueur) {
                    grade = await joueur.lire('Grade') || '';
                }
                const gradeCell = `<td align="center">${grade}</td>`;
                $(gradeCell).insertBefore(row.find(`td:eq(${initialRangColIndex})`));
            }).get();

            await Promise.all(promises);
        } else {
            // La colonne 'Grade' existe, on la met à jour
            console.log(`[${this.constructor.name}] Mise à jour de la colonne 'Grade'.`);
            const promises = $("#tabMembresAlliance tbody tr").map(async (i, elt) => {
                const row = $(elt);
                const pseudo = row.find(`td:eq(${initialPseudoColIndex})`).text().split(' ')[0];
                const joueur = membresForumMap.get(pseudo);

                let grade = '';
                if (joueur) {
                    grade = await joueur.lire('Grade') || '';
                }
                row.find(`td:eq(${gradeColIndex})`).text(grade);
            }).get();

            await Promise.all(promises);
        }
    }
});

;
// Source: js/class/fonctionnalite/alliance/JoueursExterieurs.js
Utils.register(class JoueursExterieurs extends FonctionnaliteAlliance {
    /**
     * @property {string[]} ABREVIATIONS_HISTORY - Historique des abréviations
     */
    static ABREVIATIONS_HISTORY = ['JEX'];

    /**
     * Exécute la fonctionnalité.
     * @async
     * @returns {Promise<void>}
     */
    async run() {
        await this.page.synchroniserJoueursDepuisDOM();
        const joueursDejaDansTableau = Object.keys(this.page._alliance.joueurs);
        let tousLesMembres;
        await this.executerTransaction(async () => {
            tousLesMembres = await this.chargerObjetsForum(Joueur, false);
        });
        const tousLesMembresMap = new Map();
        for (const m of tousLesMembres) {
            tousLesMembresMap.set(await m.lire('Pseudo'), m);
        }

        const membresExterieurs = [];
        for (const membre of tousLesMembres) {
            if (!joueursDejaDansTableau.includes(await membre.lire('Pseudo'))) {
                membresExterieurs.push(membre);
            }
        }
        console.log('membresExterieurs: ', membresExterieurs);

        if (membresExterieurs.length > 0) {

            const pseudoColIndex = this.page.getColonneIndex('Pseudo');
            let tagAllianceColIndex = this.page.getColonneIndex('Tag Alliance');

            if (tagAllianceColIndex === -1) {
                // Créer la colonne "Tag Alliance" juste après "Pseudo"
                $('<th>Tag Alliance</th>').insertAfter($(`#tabMembresAlliance thead tr th:eq(${pseudoColIndex})`));
                tagAllianceColIndex = pseudoColIndex + 1;
                console.log(`[${this.constructor.name}] Colonne 'Tag Alliance' créée.`);
            }

            // Peupler la colonne pour tous les joueurs déjà dans le tableau
            const promises = $("#tabMembresAlliance tbody tr").map(async (i, elt) => {
                const row = $(elt);
                const pseudo = row.find(`td:eq(${pseudoColIndex})`).text().split(' ')[0];
                const joueur = tousLesMembresMap.get(pseudo);

                let tag = '';
                if (joueur) {
                    const tagBrut = await joueur.lire('Tag Alliance');
                    if (tagBrut) {
                        tag = `<a href="classementAlliance.php?alliance=${encodeURIComponent(tagBrut)}" target="_blank">${tagBrut}</a>`;
                    }
                }
                const tagCell = `<td align="center">${tag}</td>`;
                $(tagCell).insertAfter(row.find(`td:eq(${pseudoColIndex})`));
            }).get();
            await Promise.all(promises);

            // Ajouter les lignes des joueurs extérieurs
            const headers = [];
            $("#tabMembresAlliance thead tr th").each(function () {
                headers.push($(this).text().trim());
            });

            for (const membre of membresExterieurs) {
                const $corps = await membre.afficherCorps(headers);
                $("#tabMembresAlliance tbody").append($corps);
                const pseudo = await membre.lire('Pseudo');
                console.log(`[${this.constructor.name}] Ligne ajoutée pour le joueur ${pseudo}.`);
            }
        } else {
            console.log(`[${this.constructor.name}] Aucun joueur extérieur à ajouter.`);
        }
    }
});

;
// Source: js/class/fonctionnalite/alliance/ModifierGrade.js
Utils.register(class ModifierGrade extends FonctionnaliteAlliance {
    /**
     * @property {string[]} ABREVIATIONS_HISTORY - Historique des abréviations
     */
    static ABREVIATIONS_HISTORY = ['MGR'];

    /**
     * @property {string} NIVEAU_DROIT_OUTIIIL_REQUIS - Niveau de droit requis pour cette fonctionnalité
     */
    static NIVEAU_DROIT_OUTIIIL_REQUIS = 'A';

    /**
     * Exécute la fonctionnalité.
     * @async
     * @returns {Promise<void>}
     */
    async run() {
        let membresForum;
        await this.executerTransaction(async () => {
            membresForum = await this.chargerObjetsForum(Joueur, false);
        });
        const membresForumMap = new Map();
        for (const j of membresForum) {
            const pseudo = await j.lire('Pseudo');
            const id = await j.lire('Id');
            membresForumMap.set(pseudo, { joueur: j, id });
        }

        const pseudoColIndex = this.page.getColonneIndex('Pseudo');

        // Parcourir toutes les lignes pour ajouter l'icône de modification
        $("#tabMembresAlliance tbody tr").each((i, elt) => {
            const pseudo = $(elt).find(`td:eq(${pseudoColIndex})`).text().split(' ')[0];
            const data = membresForumMap.get(pseudo);

            if (data) {
                const premierTd = $(elt).find('td:eq(0)');
                if (premierTd.find('img[alt="grade"]').length > 0) {
                    return;
                }
                const { joueur, id } = data;
                const bouton = $(`<a href="#"><img src="${IMG_UTILITY}" alt="grade"/></a>`);
                bouton.onActionSecurisee('click', this, (e) => {
                    const boite = new BoiteGrade(joueur, this.page, id);
                    boite.afficher();
                });
                premierTd.append(bouton);
            }
        });
    }

});

